// 扩展书标记：职业名中的【xxx】代表来自对应扩展书
export const EXP_BOOKS = [
  'TRPG-JAPAN',
  '克苏鲁神话2010',
  '克苏鲁神话2015',
  '新克苏鲁神话2020',
  '新克苏鲁神话2026',
  '纸浆克苏鲁',
];
const EXP_BOOK_SET = new Set(EXP_BOOKS);

// 提取职业名中所有扩展书标记（用于按来源过滤；部分职业带多个标记，如 A・B）
export function getExpBooks(name) {
  const matches = name.match(/【([^】]+)】/g) || [];
  return matches.map(m => m.slice(1, -1)).filter(b => EXP_BOOK_SET.has(b));
}

